-- 299: Original BrillaPrep WASSCE BrillaPrep transitional Music beta content blueprint questions, part 7.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_299_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_299_guard;
INSERT INTO _migration_299_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_031' AND NOT (q.topic_id IS 'topic_was_music_b005_7' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which feature commonly links highlife performance to dance-band practice?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Their musical features developed through distinct Black historical and social experiences","B. Creating or reshaping music in real time within an understood framework","C. Syncopated dance rhythms combined with melodic ensemble playing","D. Its characteristic rhythmic pattern, metre, tempo and instrumentation"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Highlife developed through Ghanaian social dance settings and blends local rhythmic language with guitar, brass or band textures. Therefore the correct answer is C: Syncopated dance rhythms combined with melodic ensemble playing.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_031' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_299_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_032' AND NOT (q.topic_id IS 'topic_was_music_b005_7' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is context important when comparing spirituals, gospel, blues and jazz?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Creating or reshaping music in real time within an understood framework","B. Its characteristic rhythmic pattern, metre, tempo and instrumentation","C. Evidence distinguishes documented influence from unsupported praise","D. Their musical features developed through distinct Black historical and social experiences"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Accurate comparison relates sound to community, worship, labour, migration and performance histories rather than treating labels as interchangeable. Therefore the correct answer is D: Their musical features developed through distinct Black historical and social experiences.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_032' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_299_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_033' AND NOT (q.topic_id IS 'topic_was_music_b005_7' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does improvisation require from a performer?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Creating or reshaping music in real time within an understood framework","B. Its characteristic rhythmic pattern, metre, tempo and instrumentation","C. Evidence distinguishes documented influence from unsupported praise","D. Syncopated dance rhythms combined with melodic ensemble playing"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Improvisation is purposeful musical decision-making guided by style, harmony, rhythm, form and interaction with other performers. Therefore the correct answer is A: Creating or reshaping music in real time within an understood framework.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_033' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_299_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_034' AND NOT (q.topic_id IS 'topic_was_music_b005_7' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which listening evidence best supports identifying a dance genre?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Evidence distinguishes documented influence from unsupported praise","B. Its characteristic rhythmic pattern, metre, tempo and instrumentation","C. Syncopated dance rhythms combined with melodic ensemble playing","D. Their musical features developed through distinct Black historical and social experiences"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Genre identification should rest on combined audible features rather than a title, costume or performer name alone. Therefore the correct answer is B: Its characteristic rhythmic pattern, metre, tempo and instrumentation.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_034' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_299_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_035' AND NOT (q.topic_id IS 'topic_was_music_b005_7' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should a musician’s contribution be described with specific works or innovations?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Syncopated dance rhythms combined with melodic ensemble playing","B. Their musical features developed through distinct Black historical and social experiences","C. Evidence distinguishes documented influence from unsupported praise","D. Creating or reshaping music in real time within an understood framework"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Connecting a musician to identifiable repertoire, techniques or institutions produces a defensible account of musical significance. Therefore the correct answer is C: Evidence distinguishes documented influence from unsupported praise.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_035' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-