INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_music_b005_031', 'topic_was_music_b005_7', 'subj_wassce_music', 'exam_wassce', NULL, NULL, 'Which feature commonly links highlife performance to dance-band practice?', 'multiple_choice', NULL, '["A. Their musical features developed through distinct Black historical and social experiences","B. Creating or reshaping music in real time within an understood framework","C. Syncopated dance rhythms combined with melodic ensemble playing","D. Its characteristic rhythmic pattern, metre, tempo and instrumentation"]', 'C', 'Highlife developed through Ghanaian social dance settings and blends local rhythmic language with guitar, brass or band textures. Therefore the correct answer is C: Syncopated dance rhythms combined with melodic ensemble playing.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_music_b005_7', 'Identify', 'AO1', NULL, NULL, 'board_waec');
